                print("Binary files differ (diff skipped)")
                print()
            continue

        a_label = f"a/{rel_path}"
        b_label = f"b/{rel_path}"

        if old_hash is None:
            old_content = []
            a_label = "/dev/null"
        if new_hash is None:
